shellCommands.command:
node -e "
const rp=require('./node_modules/react/package.json'); console.log('react:', rp.version);
const rd=require('./node_modules/react-dom/package.json'); console.log('react-dom:', rd.version);
" && echo "--- grep ViewTransition in react ---" && grep -ro "unstable_ViewTransition\|ViewTransition" node_modules/react/cjs/*.js | sort -u | head -10 && echo "--- addTransitionType ---" && grep -ro "addTransitionType" node_modules/react/cjs/*.js | sort -u | head -5 && echo "(end)"
